		#region Constructors

		public PickLinesUserControl()
		{
			WhsNotificationSubscriberGuiHelper = ObjectFactory.Get<INotificationSubscriberQueryUser>(nameof(WhsNotificationSubscriberGuiHelper));
			InitializeComponent();
			AddContextMenuItems();

			ItemsGrid.RemoveAction = RemoveAction.NoRemovePossible;
			InventoryGrid.RemoveAction = RemoveAction.NoRemovePossible;
