		#region AddContextMenuItems

		void AddContextMenuItems()
		{
			var assignSelectedLinesToUserMenuItem = new ZMenuItem(ResString.GetMultilingualString("7eecb8f3-867f-4bf6-992c-12bd39f49a07", "Assign Selected Lines to User"), AssignSelectedLinesContextMenu_Click);
			var unAssignSelectedLinesMenuItem = new ZMenuItem(ResString.GetMultilingualString("93831878-50eb-4b70-9617-f71d31746efd", "Un-assign Selected Lines"), UnAssignSelectedLinesContextMenu_Click);
			InventoryGrid.ContextMenu.Popup += delegate
			{
				var selectedBizO = InventoryGrid.SelectedElements;
				var allowLinesAssignmentUpdate = !Pick.IsFinalisedOrCancelled && selectedBizO.Length != 0 && selectedBizO.Cast<ILineStaffAssigner>().Any(l => l.CanAssignOrUnAssignLine());
				assignSelectedLinesToUserMenuItem.Enabled = allowLinesAssignmentUpdate;
				unAssignSelectedLinesMenuItem.Enabled = allowLinesAssignmentUpdate;
			};

			InventoryGrid.ContextMenu.MenuItems.Add(assignSelectedLinesToUserMenuItem);
			InventoryGrid.ContextMenu.MenuItems.Add(unAssignSelectedLinesMenuItem);
		}

		#endregion

		#endregion

		void PickLinesUserControl_Load(object sender, EventArgs e)
		{
			InventoryGrid.SetAvailability(!(Pick?.IsFinalised ?? false), new[] { "QuantityAvailableToPick", "Allocate", "QuantityTotal", "QuantityCommitted", "QuantityCrossDocked" }); // SuppressCodeSmell Reason = column name constants are not multilingual

			var isInwardProcessingEnabled = ObjectFactory.Get<Enterprise.Integration.Customs.ISupportedForProcessing>().IsSupportedForProcessing();
			InventoryGrid.SetAvailability(isInwardProcessingEnabled, new[] { WhsPickAvailableInventory.Schema.AllocationKey });
			ItemsGrid.SetAvailability(isInwardProcessingEnabled, new[] { WhsPickOrderedInventory.Schema.AllocationKey });
			RefreshItemsGuidToUpdateDisplayedCustomColumns();

			var isHeldInventoryOrder = WarehouseDataRegistry.Instance.EnableHeldGoodsForOrders.Value && (Pick?.IsHeldInventoryOrderPick ?? false);
			ItemsGrid.SetAvailability(isHeldInventoryOrder, nameof(WhsPickOrderedInventory.OrderedHeldCode));
			InventoryGrid.SetAvailability(isHeldInventoryOrder, nameof(WhsPickAvailableInventory.HoldCode));

			InventoryToPickGroupBox.CaptionResourceString = isHeldInventoryOrder
				? Enterprise.Warehouse.Transactions.GUI.Res.GetData("D96E188A-4944-434F-A51A-2434FBB7A690", "Held Inventory")
				: Enterprise.Warehouse.Transactions.GUI.Res.GetData("160167A1-F5F9-44DF-BB80-A0876DA2857C", "Available Inventory");
		}

		void RefreshItemsGuidToUpdateDisplayedCustomColumns()
		{
			if (Pick?.WP_WW_Whs.IsValid ?? false)
			{
				itemsGridLayoutPersister.ConfigOrgChanged();
			}
		}

		#region ZUserControl Overloads

		protected override void OnCurrentDataItemChanging(EventArgs e)
		{
			base.OnCurrentDataItemChanging(e);

			CurrencyManager cm = (CurrencyManager)GetBindingManager(ItemsGrid.BindTo);
			if (cm != null)
			{
				cm.CurrentChanged -= new EventHandler(OnItemCurrentChanged);
			}

			if (Pick != null)
			{
				Pick.WP_WW_WhsInfo.ValueChanged -= OnWarehouseChanged;
			}
		}

		protected override void OnCurrentDataItemChanged(EventArgs e)
		{
			base.OnCurrentDataItemChanged(e);

			CurrencyManager cm = (CurrencyManager)GetBindingManager(ItemsGrid.BindTo);
			if (cm != null)
			{
				cm.CurrentChanged += new EventHandler(OnItemCurrentChanged);
				CreateGridLayoutControllers();
				OnItemCurrentChanged(null, EventArgs.Empty);
			}

			if (Pick != null)
			{
				Pick.WP_WW_WhsInfo.ValueChanged += OnWarehouseChanged;
				UOMGroupBox.Visible = Pick.IsPickByUOMEnabled;
				GroupBoxPickByPickedDetails.Visible = !Pick.IsPickByUOMEnabled;
			}

			OnWarehouseChanged(null, EventArgs.Empty);
		}

		#region CreateGridLayoutControllers

		void CreateGridLayoutControllers()
		{
			if (itemsGridLayoutPersister == null)
			{
				itemsGridLayoutPersister = new CustomLabelsGridLayoutPersister(ItemsGrid, new WhsPickOrderedInventory.CustomLabelsProvider(Pick));
				orderedInventoriesPartAttributeColumnManager = new PartAttributeColumnManager(ItemsGrid, "ExpiryDate", "PackingDate", "PartAttrib1", "PartAttrib2", "PartAttrib3", "SerialNumber");
				pickInventoryPartAttributeColumnManager = new PartAttributeColumnManager(InventoryGrid, "ExpiryDate", "PackingDate", "PartAttrib1", "PartAttrib2", "PartAttrib3", "SerialNumber");
			}
		}

		#endregion

		#region OnItemCurrentChanged

		void OnItemCurrentChanged(object sender, EventArgs e)
		{
			if (IsOkToHandleItemChange)
			{
				isHandlingOnItemCurrentChange = true;
				try
				{
					OnItemCurrentChangedCore();
				}
				finally
				{
					isHandlingOnItemCurrentChange = false;
				}
			}
		}

		#region IsOkToHandleItemChange

		bool IsOkToHandleItemChange
		{
			get { return !isHandlingOnItemCurrentChange && itemsGridLayoutPersister != null; }
		}

		bool isHandlingOnItemCurrentChange;

		#endregion

		#region OnItemCurrentChangedCore

		void OnItemCurrentChangedCore()
		{
			CurrencyManager cm = (CurrencyManager)GetBindingManager(ItemsGrid.BindTo);
			if (cm != null && cm.Count > 0)
			{
				WhsPickOrderedInventory orderedInventory = (WhsPickOrderedInventory)cm.GetCurrent();
				if (orderedInventory != null)
				{
					MinimumShelfLife = orderedInventory.MinimumShelfLife;
					ChangeGridLayoutsForClient(orderedInventory.Client);

					var serialNumberGridVisibility = orderedInventory.AvailableInventories.Cast<WhsPickAvailableInventory>().FirstOrDefault()?.HasSerialNumber ?? false;
					AdjustSerialNumberGrid(serialNumberGridVisibility);
				}
			}

			void AdjustSerialNumberGrid(bool visible)
			{
				SerialNumberSelector.Visible = visible;
				var serialNumberGridWidth = ControlDpiScalingHelper.ScaleToCurrentDpiX(visible ? 225 : 25);
				ControlDpiScalingHelper.SetWidth(ref InventoryGrid, InventoryToPickGroupBox.Width - serialNumberGridWidth, false);
			}
		}

		void ChangeGridLayoutsForClient(OrgHeader client)
		{
			if (client != null && client != prevInventoryClient)
			{
				orderedInventoriesPartAttributeColumnManager.SetColumns(client);
				pickInventoryPartAttributeColumnManager.SetColumns(client);

				Pick.CustomLabelsGridLayoutPersister_ConfigOrg = client;
				RefreshItemsGuidToUpdateDisplayedCustomColumns();

				SortItemsForPicking_Click(null, EventArgs.Empty);

				prevInventoryClient = client;
			}
		}

