		#region CheckIfWeCanPerformActionOnPickAndShowErrorIfNot

		bool CheckIfWeCanPerformActionOnPickAndShowErrorIfNot()
		{
			bool result = false;

			if (Pick != null)
			{
				result = true;

				if (Pick.IsFinalisedOrCancelled)
				{
					Globals.Message.ShowError(NoChangesCanBeMadeToThisPickBecauseItIsEitherFinalisedOrCancelledMsg);
					result = false;
				}
				else if (Pick.WP_IsCartonised || Pick.IsCartonising)
				{
					Globals.Message.ShowError(NoChangesCanBeMadeToThisPickBecauseItIsEitherCartonisedOrCartonisingMsg);
					result = false;
				}
				else if (Pick.IsReadyForPlanningOrPlanned)
				{
					Globals.Message.ShowError(NoChangesCanBeMadeToThisPickBecauseItIsEitherReadyForPlanningOrPlannedMsg);
					result = false;
				}
				else if (Pick.IsPickSlipPrinted)
				{
					Globals.Message.ShowWarning(NoChangesCanBeMadeToThisPickBecausePickSlipHasAlreadyBeenPrintedMsg);
				}
			}
			else
			{
				Globals.Message.ShowError(PleaseOpenThePickSlipTabToPerformThisFunction);
			}
			return result;
		}

		#endregion

