		#region Methods

		#region ShowHideUSBondedColumns

		void ShowHideUSBondedColumns()
		{
			var warehouse = (Pick != null) ? Pick.Warehouse : null;
			bool isUSBonded = warehouse.IsBondedEnabledAndUSJurisdiction();

			ItemsGrid.SetAvailability(isUSBonded, new[] { "PackageGroupId" }); // WhsPickOrderedInventory.Schema.PackageGroupID
			InventoryGrid.SetAvailability(isUSBonded, new[] { "PackageGroupId", "PerPackageQty" }); //WhsPickAvailableInventory.Schema.PackageGroupID
		}

