		#region Events

		#region ClearAllStockAllocationsButton_Click

		public void ClearAllStockAllocationsButton_Click(object sender, EventArgs e)
		{
			ClearAllStockAllocationsHandler();
		}

		void ClearAllStockAllocationsHandler()
		{
			Cursor.Current = Cursors.WaitCursor;
			try
			{
				if (Pick != null && Pick.IsPartiallyOrFullyPickedFromPutawayLocation)
				{
					Globals.Message.ShowError(CannotPerformThisOperationBecausePickIsPartiallyOrFullyPickedErrorMessage);
				}
				else if (Pick != null && Pick.IsPicking)
				{
					Globals.Message.ShowError(NoChangesCanBeMadeToThisPickBecausePickingHasCommenced);
				}
				else if (CheckIfWeCanPerformActionOnPickAndShowErrorIfNot())
				{
					Pick.ClearAllocatedItems();
					InventoryGrid.Refresh();
					SerialNumberSelector.Refresh();
				}
			}
			finally
			{
				Cursor.Current = Cursors.Default;
			}
		}

		#endregion

		#region AutoAllocateStock_Click

		public void AutoAllocateStock_Click(object sender, EventArgs e)
		{
			Cursor.Current = Cursors.WaitCursor;
			try
			{
				if (CheckIfWeCanPerformActionOnPickAndShowErrorIfNot())
				{
					var result = Pick.AutoAllocateItems();
					if (!string.IsNullOrEmpty(result))
					{
						Globals.Message.ShowWarning(result);
					}
					SerialNumberSelector.Refresh();
				}
			}
			finally
			{
				Cursor.Current = Cursors.Default;
			}
		}

		#endregion

		#region SortItemsForPicking_Click

		public void SortItemsForPicking_Click(object sender, EventArgs e)
		{
			if (Pick == null)
			{
				Globals.Message.ShowError(PleaseOpenThePickSlipTabBeforeSortingItemsMsg);
			}
			else
			{
				Cursor.Current = Cursors.WaitCursor;
				try
				{
					Pick.SortItemsForManualPicking();
				}
				finally
				{
					Cursor.Current = Cursors.Default;
				}
			}
		}

