		#region UnAssignSelectedLinesContextMenu_Click

		void UnAssignSelectedLinesContextMenu_Click(object sender, EventArgs e)
		{
			var selectedBizO = InventoryGrid.SelectedElements;
			UnAssignPickLines(selectedBizO.Cast<ILineStaffAssigner>());
		}

		#endregion

		#region UnAssignPickLines

		void UnAssignPickLines(IEnumerable<ILineStaffAssigner> lines)
		{
			foreach (var line in lines.Where(l => l.CanAssignOrUnAssignLine()))
			{
				line.UnAssignLine(null);
			}
		}

		#endregion

		#region AvailableInventoryGrid_ColourDeciding

		void AvailableInventoryGrid_ColourDeciding(object sender, ColourDecidingEventArgs e)
		{
			if (MinimumShelfLife > 0 && Pick != null && !Pick.IsFinalisedOrCancelled)
			{
				var line = (WhsPickAvailableInventory)e.ObjectAtRow;
				if (line.ExpiryDate < ZDateTime.Today.AddDays(MinimumShelfLife))
				{
					e.Colour = Color.LightSalmon;
				}
			}
		}

		#endregion

