		#region INotifications Members

		void INotifications.Add(INotification notification)
		{
			Notify(notification);
		}

		void Notify(INotification notification)
		{
			INotificationSubscriberType type = notification.Type as INotificationSubscriberType;
			if (type != null && type.Name == "Info")
			{
				Enterprise.ZArchitecture.Environment.Globals.Message.ShowInformation(notification.Message);
			}
			else if (type != null && type.Name == "Warning")
			{
				Enterprise.ZArchitecture.Environment.Globals.Message.ShowWarning(notification.Message);
			}
			else
			{
				Enterprise.ZArchitecture.Environment.Globals.Message.ShowError(notification.Message);
			}
		}

